import type jsPDF from "jspdf";

// DejaVu Sans (Bitstream Vera license): Unicode subset for clinical units and Portuguese.
export function registerReportFonts(doc: jsPDF) {
  doc.addFileToVFS("ReportSans.ttf", "");
  doc.addFileToVFS("ReportSans-Bold.ttf", "");
  doc.addFont("ReportSans.ttf", "ReportSans", "normal");
  doc.addFont("ReportSans-Bold.ttf", "ReportSans", "bold");
}
